import { intrinsicSizeMeasureFunc } from '../tools/utils.ts'
import Yoga from '@hanzo/layout';
import {
  Align,
  BoxSizing,
  Direction,
  Display,
  Edge,
  Errata,
  ExperimentalFeature,
  FlexDirection,
  GridTrackType,
  Gutter,
  Justify,
  MeasureMode,
  Overflow,
  PositionType,
  Unit,
  Wrap,
} from '@hanzo/layout';

test('grid_basic_implicit_tracks', () => {
  const config = Yoga.Config.create();

  const root = Yoga.Node.create(config);
  root.setPositionType(PositionType.Absolute);
  root.setDisplay(Display.Grid);
  const rootGridTemplateColumns = [];
  rootGridTemplateColumns.push({type: GridTrackType.Points, value: 40});
  root.setGridTemplateColumns(rootGridTemplateColumns);
  const rootGridTemplateRows = [];
  rootGridTemplateRows.push({type: GridTrackType.Points, value: 40});
  root.setGridTemplateRows(rootGridTemplateRows);

  const root_child0 = Yoga.Node.create(config);
  root.insertChild(root_child0, 0);

  const root_child1 = Yoga.Node.create(config);
  root_child1.setWidth(35);
  root_child1.setHeight(35);
  root.insertChild(root_child1, 1);
  root.calculateLayout(undefined, undefined, Direction.LTR);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(40);
  expect(root.getComputedHeight()).toBe(75);

  expect(root_child0.getComputedLeft()).toBe(0);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(40);

  expect(root_child1.getComputedLeft()).toBe(0);
  expect(root_child1.getComputedTop()).toBe(40);
  expect(root_child1.getComputedWidth()).toBe(35);
  expect(root_child1.getComputedHeight()).toBe(35);

  root.calculateLayout(undefined, undefined, Direction.RTL);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(40);
  expect(root.getComputedHeight()).toBe(75);

  expect(root_child0.getComputedLeft()).toBe(0);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(40);

  expect(root_child1.getComputedLeft()).toBe(5);
  expect(root_child1.getComputedTop()).toBe(40);
  expect(root_child1.getComputedWidth()).toBe(35);
  expect(root_child1.getComputedHeight()).toBe(35);
});
